def csvout(name,rows):
    with (HERE/name).open('w',encoding='utf-8-sig',newline='') as f:
        writer=csv.writer(f)
        for row in rows:
            writer.writerow(["'"+v if isinstance(v,str) and v.startswith(('=','+','-','@')) else v for v in row])

