        ch=chain(s,c); ids=list(dict.fromkeys(i for a in ch for i in a['selected']))
        out['budget']=c['budget'];out['internalItems']=c['internal'];out['parent']=c['parent']
        out['inherited']=[i for a in ch[:-1] for i in a['selected']]
